-- Read-only rollout check. Return counts only; never export credentials or rows.
SELECT l.id,l.name,l.source_key,count(DISTINCT t.id) AS teams,count(DISTINCT r.player_id) AS roster_players,(SELECT count(*) FROM fanta.rounds g WHERE g.league_id=l.id) AS rounds,(SELECT count(*) FROM fanta.lineups x WHERE x.league_id=l.id) AS lineups FROM fanta.leagues l LEFT JOIN fanta.teams t ON t.league_id=l.id LEFT JOIN fanta.rosters r ON r.team_id=t.id WHERE l.source_key='lucas-bar:548867' GROUP BY l.id;
SELECT count(*) AS older_open_slips_outside_lucas FROM fanta_state s CROSS JOIN LATERAL jsonb_array_elements(payload->'rounds') r CROSS JOIN LATERAL jsonb_array_elements(coalesce(r->'slips','[]')) slip WHERE r->>'source'='fantacalcio' AND coalesce(r->>'settled','false')<>'true' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(payload->'fantasyConnections','[]')) c WHERE c->>'alias'='lucas-bar' AND c->>'competitionId'='548867' AND c->>'competitionKey'=r->>'competitionKey' AND c->'leagues'?(r->>'league'));
